const items = $input.all();

return items.map((item) => {
  const payload = item.json.body ?? item.json;
  const data = payload.data ?? {};
  const fields = Array.isArray(data.fields) ? data.fields : [];

  const findField = (label) =>
    fields.find((field) => field.label === label);

  const readValue = (field) => {
    if (!field) return "";

    const value = field.value;

    // Dropdown and checkbox answers may be arrays of option IDs.
    if (Array.isArray(value)) {
      const options = Array.isArray(field.options)
        ? field.options
        : [];

      return value
        .map((selectedId) => {
          const option = options.find(
            (option) => option.id === selectedId
          );
          return option?.text ?? selectedId;
        })
        .join(", ");
    }

    return value ?? "";
  };

  const consentField = findField("Consent to contact");

  const consentDetailsField = fields.find((field) =>
    field.label?.startsWith("Consent to contact (")
  );

  const consentToContact =
    consentDetailsField?.value === true ||
    (
      Array.isArray(consentField?.value) &&
      consentField.value.length > 0
    );

  return {
    json: {
      eventId: payload.eventId ?? "",
      submissionId: data.submissionId ?? data.responseId ?? "",

      fullName: String(
        readValue(findField("Full Name"))
      ).trim(),

      email: String(
        readValue(findField("Email"))
      ).trim().toLowerCase(),

      company: String(
        readValue(findField("Company Name"))
      ).trim(),

      serviceNeeded: String(
        readValue(
          findField("Which service are you interested in?")
        )
      ).trim(),

      monthlyBudget: String(
        readValue(
          findField(
            "What is your estimated monthly budget (USD)?"
          )
        )
      ).trim(),

      consentToContact,
      receivedAt: payload.createdAt ?? ""
    }
  };
});

const lead = $json;
const errors = [];

if (
  typeof lead.fullName !== "string" ||
  !lead.fullName.trim()
) {
  errors.push("missing_full_name");
}

if (
  typeof lead.email !== "string" ||
  !lead.email.trim()
) {
  errors.push("missing_email");
} else if (
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)
) {
  errors.push("invalid_email");
}

if (
  typeof lead.serviceNeeded !== "string" ||
  !lead.serviceNeeded.trim()
) {
  errors.push("missing_service");
}

if (lead.consentToContact !== true) {
  errors.push("consent_not_given");
}

return {
  json: {
    ...lead,
    isValid: errors.length === 0,
    validationErrors: errors,
  },
};

const lead = $json;

return {
  json: {
    eventId: lead.eventId ?? "",
    submissionId: lead.submissionId ?? "",
    status: "rejected",
    reason: "validation_failed",
    validationErrors: Array.isArray(lead.validationErrors)
      ? lead.validationErrors
      : ["unknown_validation_error"],
    receivedAt: lead.receivedAt ?? "",
    handledAt: new Date().toISOString()
  }
};

